-- DEMONSTRATION DATA ONLY — generated by scripts/gen-seed.mjs from supabase/demo-properties.json. Do not edit by hand.
--
-- Six FICTIONAL listings for testing the marketplace interface, search filters, detail pages and the booking flow.
-- Every row is flagged is_sample = true: the site shows a "DEMO LISTING — SAMPLE DATA" badge, keeps them out of Google
-- (noindex, not in the sitemap) and the descriptions say so. They are NOT real properties, owners, prices or reviews, and the
-- photographs are illustrative. They have no host (platform-managed) until you assign them to YOUR OWN test host account with
-- supabase/scripts/assign_demo_listings_to_host.sql so you can test the host side of the booking flow.
--
-- Run AFTER all migrations. Safe to run twice (existing slugs are skipped).
-- Remove everything again with supabase/scripts/remove_sample_data.sql.

insert into public.properties
  (slug, name, category_id, summary, description, city, state, region, rooms_count, max_guests, bedrooms, beds, bathrooms,
   accommodation_arrangement, price_inr, price_unit, weekend_price_inr, included_guests, extra_guest_fee_inr, cleaning_fee_inr,
   tax_percent, min_nights, max_nights, check_in_time, check_out_time, house_rules, cancellation_policy,
   status, is_featured, is_sample, terms_accepted_at, photo_rights_confirmed_at, submitted_at, published_at)
values
  ('demo-green-valley-farm-stay', 'Green Valley Farm Stay', (select id from public.property_categories where slug = 'farm-stay'), 'Demo listing: a farmhouse stay among paddy fields and coconut palms.', 'DEMONSTRATION LISTING — SAMPLE DATA. This fictional farm stay shows how a family-friendly farmhouse appears on Hasiru Nidhi: two bedrooms opening onto a verandah, home-style meals and mornings among coconut palms. It is not a real property; the location, price, photographs and availability are illustrative.', 'Kanakapura', 'Karnataka', 'Ramanagara district (demo location)', 2, 5, 2, 3, 2, 'entire_property', 4200, 'per_night', 5200, 4, 600, null, 0, 1, 7, '14:00', '11:00', 'Demo house rules: quiet after 10 PM. No smoking inside. Pets are not allowed. Please keep the garden gates closed.', 'moderate', 'approved', true, true, now(), now(), now(), now()),
  ('demo-countryside-garden-cottage', 'Countryside Garden Cottage', (select id from public.property_categories where slug = 'cottage'), 'Demo listing: a standalone cottage with its own garden and fire pit.', 'DEMONSTRATION LISTING — SAMPLE DATA. A fictional one-bedroom cottage for couples and small families, with a courtyard garden and an evening fire pit. It exists only to demonstrate search, filters, price breakdowns and booking requests; nothing about it is real.', 'Devanahalli', 'Karnataka', 'Bengaluru Rural district (demo location)', 1, 3, 1, 2, 1, 'entire_property', 5200, 'per_night', 6200, null, null, null, 0, 1, 10, '13:00', '11:00', 'Demo house rules: no loud music after 9 PM. Fire pit only with the host''s supervision.', 'flexible', 'approved', false, true, now(), now(), now(), now()),
  ('demo-forest-edge-eco-retreat', 'Forest Edge Eco Retreat', (select id from public.property_categories where slug = 'eco-retreat'), 'Demo listing: a low-impact retreat at the edge of a forest.', 'DEMONSTRATION LISTING — SAMPLE DATA. A fictional eco-retreat used to demonstrate a larger group stay with a cleaning fee and a minimum stay. Solar water heating, rainwater harvesting and forest walks are described for illustration only and are not claims about any real property.', 'Sakleshpur', 'Karnataka', 'Hassan district (demo location)', 4, 8, 4, 6, 3, 'entire_property', 7500, 'per_night', null, null, null, 800, 0, 2, 14, '14:00', '10:00', 'Demo house rules: walk quietly near the forest edge. No drones. Please carry waste back to the bins provided.', 'strict', 'approved', false, true, now(), now(), now(), now()),
  ('demo-riverside-nature-escape', 'Riverside Nature Escape', (select id from public.property_categories where slug = 'nature-retreat'), 'Demo listing: a calm riverside stay with a two-night minimum.', 'DEMONSTRATION LISTING — SAMPLE DATA. A fictional riverside retreat used to test minimum-stay rules and the availability calendar. The river, the verandah corridor and the quiet mornings are illustrative; the photograph is a stand-in and does not show a real riverside property.', 'Srirangapatna', 'Karnataka', 'Mandya district (demo location)', 3, 6, 3, 4, 2, 'private_rooms', 6200, 'per_night', 7200, null, null, null, 0, 2, 10, '14:00', '11:00', 'Demo house rules: no swimming without a guide. Keep the riverside path clear at night.', 'moderate', 'approved', false, true, now(), now(), now(), now()),
  ('demo-organic-farm-experience', 'Organic Farm Experience', (select id from public.property_categories where slug = 'farm-stay'), 'Demo listing: a working-garden stay priced per guest, with harvest activities.', 'DEMONSTRATION LISTING — SAMPLE DATA. A fictional organic farm used to demonstrate per-guest pricing and activity-led stays: vegetable harvesting, composting and farm-to-table meals. None of the produce, certifications or practices described are real or verified.', 'Doddaballapura', 'Karnataka', 'Bengaluru Rural district (demo location)', 3, 8, 3, 5, 2, 'private_rooms', 1600, 'per_person_night', null, null, null, null, 0, 1, 5, '12:00', '11:00', 'Demo house rules: closed shoes in the fields. Children must be accompanied during farm activities.', 'flexible', 'approved', false, true, now(), now(), now(), now()),
  ('demo-weekend-cycling-retreat', 'Weekend Cycling Retreat', (select id from public.property_categories where slug = 'cycling-friendly'), 'Demo listing: a cycling-friendly base with early breakfasts and quiet lanes.', 'DEMONSTRATION LISTING — SAMPLE DATA. A fictional retreat for weekend riders: bicycles to borrow, early-start breakfasts and quiet tree-lined lanes. It also demonstrates a listing with weekend pricing and a two-night minimum. Nothing here describes a real business.', 'Nandi Hills', 'Karnataka', 'Chikkaballapur district (demo location)', 5, 10, 5, 8, 4, 'entire_property', 9000, 'per_night', 11000, 6, 700, null, 0, 2, 7, '13:00', '11:00', 'Demo house rules: helmets are compulsory on the cycling lanes. Bicycles must be returned by sunset.', 'moderate', 'approved', false, true, now(), now(), now(), now())
on conflict (slug) do nothing;

insert into public.property_images (property_id, path, source, alt, sort_order)
select p.id, v.path, 'static', v.alt, v.ord
  from (values
    ('demo-green-valley-farm-stay', '/images/stay/farmhouse-tiled-roof-verandah-karnataka.jpg', 'Tiled-roof farmhouse verandah (illustrative image)', 0),
    ('demo-green-valley-farm-stay', '/images/hero/hero-sunrise-paddy-coconut-karnataka.jpg', 'Sunrise over paddy and coconut palms (illustrative image)', 1),
    ('demo-countryside-garden-cottage', '/images/stay/farmhouse-cottage-courtyard-karnataka.jpg', 'Cottage courtyard (illustrative image)', 0),
    ('demo-countryside-garden-cottage', '/images/gardening/marigold-flowers-garden-karnataka.jpg', 'Marigold flower beds (illustrative image)', 1),
    ('demo-forest-edge-eco-retreat', '/images/gallery/forest-valley-dusk-western-ghats.jpg', 'Forest valley at dusk (illustrative image)', 0),
    ('demo-forest-edge-eco-retreat', '/images/landscaping/forest-path-red-soil-karnataka.jpg', 'Forest path with red soil (illustrative image)', 1),
    ('demo-riverside-nature-escape', '/images/stay/verandah-corridor-karnataka.jpg', 'A long verandah corridor (illustrative image)', 0),
    ('demo-riverside-nature-escape', '/images/cycling/scenic-plantation-road-karnataka.jpg', 'A scenic plantation road (illustrative image)', 1),
    ('demo-organic-farm-experience', '/images/gardening/assorted-vegetables-harvest-karnataka.jpg', 'Freshly harvested vegetables (illustrative image)', 0),
    ('demo-organic-farm-experience', '/images/gardening/mixed-vegetable-harvest-karnataka.jpg', 'A mixed vegetable harvest (illustrative image)', 1),
    ('demo-weekend-cycling-retreat', '/images/cycling/family-of-three-cycling-tree-lane-karnataka.jpg', 'A family cycling on a tree-lined lane (illustrative image)', 0),
    ('demo-weekend-cycling-retreat', '/images/cycling/rural-road-coconut-trees-karnataka.jpg', 'A rural road lined with coconut trees (illustrative image)', 1)
  ) as v(slug, path, alt, ord)
  join public.properties p on p.slug = v.slug
 where not exists (select 1 from public.property_images i where i.property_id = p.id and i.path = v.path);

